insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-do-notifications-work-for-my-application', 'How do notifications work for my application?', '<p>Email and in-app alerts for viewing updates, contracts, and payments. Manage in <a href="/account">My Account</a> notifications settings.</p>', 'How do notifications work for my application?', 67, true from public.faq_categories where slug = 'viewings-applications' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-agents-show-properties-on-weekends', 'Can agents show properties on weekends?', '<p>Many viewings happen Friday–Saturday. Request preferred slots when booking or via <a href="/pages/contact">contact our team</a>.</p>', 'Can agents show properties on weekends?', 68, true from public.faq_categories where slug = 'viewings-applications' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'where-is-the-full-step-by-step-application-guide', 'Where is the full step-by-step application guide?', '<p>Read <a href="/pages/how-it-works">How It Works</a> for inquiry → viewing → contract → payment → handover. Rent-specific: <a href="/pages/renting-guide">Renting Guide</a>. Buy-specific: <a href="/pages/buying-guide">Buying Guide</a>.</p>', 'Where is the full step-by-step application guide?', 69, true from public.faq_categories where slug = 'viewings-applications' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'when-do-i-receive-my-tenancy-contract', 'When do I receive my tenancy contract?', '<p>After agent approval of your application and contract request in <a href="/account/transactions">property applications</a>. Download from your dashboard when ready.</p>', 'When do I receive my tenancy contract?', 70, true from public.faq_categories where slug = 'contracts-legal' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-do-i-upload-a-signed-contract', 'How do I upload a signed contract?', '<p>Sign the PDF, scan or photograph, upload in <a href="/account/transactions">property applications</a>. Agent reviews within 1–2 business days.</p>', 'How do I upload a signed contract?', 71, true from public.faq_categories where slug = 'contracts-legal' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-if-my-signed-contract-is-rejected', 'What if my signed contract is rejected?', '<p>Agent requests re-upload with notes — fix signatures, dates, or initials and resubmit via <a href="/account/transactions">property applications</a>.</p>', 'What if my signed contract is rejected?', 72, true from public.faq_categories where slug = 'contracts-legal' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'is-the-tenancy-contract-legally-binding-in-dubai', 'Is the tenancy contract legally binding in Dubai?', '<p>Yes — once signed and Ejari-registered per RERA. Review <a href="/pages/terms">Terms of Service</a> and ask questions before signing.</p>', 'Is the tenancy contract legally binding in Dubai?', 73, true from public.faq_categories where slug = 'contracts-legal' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-a-sale-and-purchase-agreement-spa', 'What is a Sale and Purchase Agreement (SPA)?', '<p>The binding contract for property sales outlining price, payment plan, and completion date. Generated through <a href="/account/transactions">property applications</a> for buyers.</p>', 'What is a Sale and Purchase Agreement (SPA)?', 74, true from public.faq_categories where slug = 'contracts-legal' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-i-review-a-contract-before-committing', 'Can I review a contract before committing?', '<p>Yes — contracts are shared for review before payment. Never pay before reviewing your breakdown in <a href="/account/transactions">property applications</a>.</p>', 'Can I review a contract before committing?', 75, true from public.faq_categories where slug = 'contracts-legal' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-personal-data-goes-on-a-contract', 'What personal data goes on a contract?', '<p>Name, ID, contact, and property details from <a href="/account/profile">My Profile</a>. Keep <a href="/account/profile">My Profile</a> updated for accuracy.</p>', 'What personal data goes on a contract?', 76, true from public.faq_categories where slug = 'contracts-legal' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'are-digital-signatures-accepted', 'Are digital signatures accepted?', '<p>Scanned wet signatures are standard; some developers accept e-sign. Your agent confirms format in <a href="/account/transactions">property applications</a>.</p>', 'Are digital signatures accepted?', 77, true from public.faq_categories where slug = 'contracts-legal' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-an-addendum-to-a-tenancy-contract', 'What is an addendum to a tenancy contract?', '<p>A supplemental document modifying terms (e.g. pet clause, maintenance). Attached to main contract in <a href="/account/transactions">property applications</a>.</p>', 'What is an addendum to a tenancy contract?', 78, true from public.faq_categories where slug = 'contracts-legal' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'who-holds-the-original-tenancy-contract', 'Who holds the original tenancy contract?', '<p>Both parties receive copies; Ejari registration holds the official record. Digital copies in <a href="/account/transactions">property applications</a>.</p>', 'Who holds the original tenancy contract?', 79, true from public.faq_categories where slug = 'contracts-legal' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-rera-form-f-for-sales', 'What is RERA Form F for sales?', '<p>Memorandum of Understanding between buyer and seller before SPA. Used in resale <a href="/collection/sales">properties for sale</a> transactions.</p>', 'What is RERA Form F for sales?', 80, true from public.faq_categories where slug = 'contracts-legal' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-i-assign-my-off-plan-contract-to-another-buyer', 'Can I assign my off-plan contract to another buyer?', '<p>Developer assignment policies vary; fees may apply. <a href="/pages/contact">contact our team</a> before any assignment.</p>', 'Can I assign my off-plan contract to another buyer?', 81, true from public.faq_categories where slug = 'contracts-legal' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-happens-if-the-seller-withdraws-after-mou', 'What happens if the seller withdraws after MOU?', '<p>MOU terms define forfeiture and remedies. Legal review recommended for high-value deals — <a href="/pages/contact">contact our team</a>.</p>', 'What happens if the seller withdraws after MOU?', 82, true from public.faq_categories where slug = 'contracts-legal' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'is-my-contract-data-kept-private', 'Is my contract data kept private?', '<p>Yes — per <a href="/pages/privacy">Privacy Policy</a>. Only assigned agents and admins access <a href="/account/transactions">property applications</a> documents.</p>', 'Is my contract data kept private?', 83, true from public.faq_categories where slug = 'contracts-legal' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-language-are-contracts-written-in', 'What language are contracts written in?', '<p>English is standard; Arabic versions may be provided for official registration. Bilingual Ejari is common.</p>', 'What language are contracts written in?', 84, true from public.faq_categories where slug = 'contracts-legal' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'do-i-need-attestation-for-overseas-buyers', 'Do I need attestation for overseas buyers?', '<p>Some transactions require notarized documents from abroad. <a href="/pages/contact">contact our team</a> for country-specific requirements.</p>', 'Do I need attestation for overseas buyers?', 85, true from public.faq_categories where slug = 'contracts-legal' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-a-security-cheque-vs-rental-cheque', 'What is a security cheque vs rental cheque?', '<p>Security cheque covers damages (refundable); rental cheques pay rent per schedule. Both explained in <a href="/pages/renting-guide">Renting Guide</a>.</p>', 'What is a security cheque vs rental cheque?', 86, true from public.faq_categories where slug = 'contracts-legal' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-contract-terms-be-negotiated', 'Can contract terms be negotiated?', '<p>Some clauses (rent, cheques, break terms) are negotiable with owner approval. Your agent advocates during <a href="/account/transactions">property applications</a>.</p>', 'Can contract terms be negotiated?', 87, true from public.faq_categories where slug = 'contracts-legal' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-long-is-contract-review-turnaround', 'How long is contract review turnaround?', '<p>Agent review of uploaded contracts: typically 1–2 business days. You are notified in <a href="/account">My Account</a>.</p>', 'How long is contract review turnaround?', 88, true from public.faq_categories where slug = 'contracts-legal' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'where-are-contract-and-legal-faqs-for-handover', 'Where are contract and legal FAQs for handover?', '<p>See <a href="/pages/shipping">Handover Information</a> for post-contract steps and this section for signing. Full journey: <a href="/pages/how-it-works">How It Works</a>.</p>', 'Where are contract and legal FAQs for handover?', 89, true from public.faq_categories where slug = 'contracts-legal' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'when-can-i-pay-for-my-property-application', 'When can I pay for my property application?', '<p>After signed contract approval and invoice generation in <a href="/account/transactions">property applications</a>. See payment section when status is Payment Pending.</p>', 'When can I pay for my property application?', 90, true from public.faq_categories where slug = 'payments-fees' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-appears-in-my-payment-breakdown', 'What appears in my payment breakdown?', '<p>Rent or sale price, deposit, agency commission, admin fees, Ejari, VAT where applicable. Itemised before invoice in <a href="/account/transactions">property applications</a>.</p>', 'What appears in my payment breakdown?', 91, true from public.faq_categories where slug = 'payments-fees' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
